test('COGS HTTP: authenticated Manager report/CSV, Staff/Lead denial, Admin mapping and CSRF',async()=>{const {UserAccounts,NamedSessionStore}=require('../accounts/service'),{createUser}=require('../review/auth'),{createReviewServer}=require('../review/server');const password='Synthetic-cogs-tests-2026',cred=await createUser('http-owner','ADMIN',password),accounts=new UserAccounts(pool);await accounts.bootstrap([cred]);const actor={id:cred.id,role:'ADMIN'},server=createReviewServer({service:f.service,users:[cred],accounts,sessionStore:new NamedSessionStore(pool),cogs:svc});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;const req=(p,body,cookie,csrf)=>fetch(base+p,{method:body?'POST':'GET',headers:{Origin:base,'Content-Type':'application/json',...(cookie?{Cookie:cookie}:{}),...(csrf?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});try{assert.equal((await req('/api/reporting/cogs')).status,401);for(const asset of ['cogs-ui.js','cogs-model.js','mapping-ui.js'])assert.equal((await req('/'+asset)).status,200);for(const role of ['ADMIN','MANAGER','STAFF','LEAD']){const p=await accounts.create(actor,{name:role,username:'cogs-'+role.toLowerCase(),email:null,role,status:'active'});await accounts.establish({token:p.setup.token,password});const l=await req('/api/login',{username:p.user.username,password}),cookie=l.headers.get('set-cookie').split(';')[0],me=await (await req('/api/me',null,cookie)).json(),allowed=['ADMIN','MANAGER'].includes(role);for(const endpoint of ['', '/csv','/detail?id='+uuid()+'&start='+day+'&end='+day])assert.equal((await req('/api/reporting/cogs'+endpoint,null,cookie)).status,allowed?200:403);assert.equal((await req('/api/reporting/cogs/mappings',null,cookie)).status,role==='ADMIN'?200:403);for(const ep of ['/mapping-settings','/mapping-badge','/mapping-history?id='+uuid()])assert.equal((await req('/api/reporting/cogs'+ep,null,cookie)).status,role==='ADMIN'?200:403);assert.equal((await req('/api/reporting/cogs/mapping-bulk',{confirmed:true,entries:[]},cookie,'bad')).status,403);if(role!=='ADMIN')assert.equal((await req('/api/reporting/cogs/mapping-settings',{expectedVersion:1,categoryIds:[]},cookie,me.csrf)).status,403);if(role!=='ADMIN')assert.equal((await req('/api/reporting/cogs/mapping-bulk',{confirmed:true,entries:[]},cookie,me.csrf)).status,403);assert.equal((await req('/api/reporting/cogs/rebuild',period,cookie,'bad')).status,403);if(!allowed)assert.equal((await req('/api/reporting/cogs/rebuild',period,cookie,me.csrf)).status,403);}}finally{server.closeAllConnections();await new Promise(r=>server.close(r));}});
test('COGS: Toast modifier reordering is semantically idempotent and does not invalidate cached costs',async()=>{const mod=()=>({guid:uuid(),quantity:'1',price:'0',modifiers:[]}),a=mod(),b=mod(),c=mod(),d=mod();a.modifiers=[c,d];const source=order({}, {},{modifiers:[a,b],appliedDiscounts:[{discountAmount:'2'},{discountAmount:'1'}]});const one=normalize(source,day);await ingest(one);await result();source[0].checks[0].selections[0].modifiers.reverse();a.modifiers.reverse();source[0].checks[0].selections[0].appliedDiscounts.reverse();const two=normalize(source,day);assert.deepEqual(one,two);await ingest(two);assert.equal((await svc.report(admin,period)).dirtyRows,0);assert.equal((await pool.query('SELECT count(*) FROM wahi_v2.sales_fact_versions')).rows[0].count,'1');});
