test('Mapping: Ignored to Mapped, Change Mapping, Remove Mapping are audited and require confirmation',async()=>{const {r}=await recipe(),a=fact();await ingest([a]);await map(a.itemId,r,{state:'excluded',recipeId:null,quantity:null,unit:null});await assert.rejects(map(a.itemId,r,{expectedVersion:1,confirmed:false}),e=>e.code==='mapping_confirmation_required');await map(a.itemId,r,{expectedVersion:1});await legacyMap(a.itemId,r,{expectedVersion:2,quantity:'2',reason:'Correct serving'});assert.equal((await result()).summary.total,'4.000000000000');await map(a.itemId,r,{expectedVersion:3,state:'unmapped',recipeId:null,quantity:null,unit:null});assert.equal((await result()).summary.quantity,'0');const h=await svc.mappingHistory(admin,{id:a.itemId});assert.equal(h.events.length,4);assert.equal(h.events[0].next.action,'mapping_removed');assert.equal(h.events[1].next.reason,'Correct serving');assert.equal(h.events[2].next.action,'ignore_replaced_by_mapping');assert.ok(h.events.every(e=>e.actor_id===admin.id));});
