test('Mapping: partial mapping immediately improves report; two reconciliations and revenue coverage',async()=>{const {r}=await recipe(),a=fact({quantity:'3',netSales:'30'}),b=fact({quantity:'2',netSales:'20'}),c=fact({quantity:'5',netSales:'50'});await ingest([a,b,c]);await map(a.itemId,r);await map(c.itemId,r,{state:'excluded',recipeId:null,quantity:null,unit:null});const d=await result();assert.equal(d.summary.quantity,'3');assert.equal(d.summary.total,'6.000000000000');assert.equal(d.summary.unmappedQuantity,'2');assert.equal(d.summary.excludedQuantity,'5');assert.equal(d.summary.coverage.historical.quantity,'3');assert.equal(d.summary.coverage.unresolved.quantity,'0');assert.deepEqual(d.summary.mappingCoverage,{mapped:'30.00',needsMapping:'20.00',ignored:'50.00'});assert.equal(d.summary.netSales,'30.000000000000');assert.equal(d.summary.applicableNetSales,'100.000000000000');assert.equal(d.summary.netSalesMappingCoverage,'30.00');assert.equal(d.reconciled,true);const q=await svc.mappings(admin,period);assert.equal(q.coverage.unitsPercent,'30.00');assert.equal(q.coverage.netSalesPercent,'30.00');});
