test('Mapping: opening report automatically refreshes only dirty mapped item with preserved return period',async()=>{const vm=require('node:vm'),source=await fs.readFile(path.join(__dirname,'../review/public/cogs-ui.js'),'utf8'),nodes=new Map(),node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',innerHTML:'',addEventListener(){}});return nodes.get(id);};const {r}=await recipe(),a=fact(),b=fact();await ingest([a,b]);await result();await map(a.itemId,r);const builds=[];const ctx=vm.createContext({URLSearchParams,Date,location:{hash:'#reporting/cogs?start='+day+'&end='+day},can:()=>true,$:node,api:async(p,body)=>{if(p.endsWith('/rebuild')){builds.push(await svc.rebuild(admin,body));return builds.at(-1);}return svc.report(admin,period);},esc:x=>String(x??''),link:(p,l)=>`<a href="#${p}">${l}</a>`,form(){},bind(){},document:{querySelectorAll:()=>[]},WahiCogs:ranges,WahiCurrency:require('../review/public/currency')});vm.runInContext(source,ctx);await vm.runInContext("cogsPage('cogs')",ctx);assert.equal(builds.length,1);assert.equal(builds[0].built,1);assert.match(node('main').innerHTML,/1 Toast items need mapping/);assert.match(node('cogs-table').innerHTML,new RegExp('item='+b.itemId));assert.match(node('cogs-table').innerHTML,/start=2026-09-15&end=2026-09-15/);assert.equal((await svc.report(admin,period)).summary.total,'2.000000000000');});
// Mapping category policy and complete finished Recipe execution.
async function category(name){return (await f.run('createRecipeCategory',{name,sortOrder:1,active:true})).id;}
async function settings(ids){const s=await svc.review.settings(admin);return svc.review.saveSettings(admin,{expectedVersion:s.version,categoryIds:ids});}
async function categorized(name,categoryId,amount='2',output='1'){const p=await f.bought(name+' component',amount),r=await f.recipe(name,[{ingredientId:p.id,quantity:'1',unit:'each'}],output,'each');await f.run('setRecipeCategory',{recipeId:r.id,categoryId,effectiveAt:early});return {p,r};}
test('Settings: migration initially enables only existing Final and Drink category IDs',async()=>{const names=['Final','Drink','Prep','Syrup','Garnish'],ids={};for(const n of names)ids[n]=await category(n);const sql=await fs.readFile(path.join(__dirname,'../migrations/018_cogs_mapping_settings.sql'),'utf8');await pool.query(sql.match(/INSERT INTO wahi_v2\.cogs_eligible_categories\(category_id\)[\s\S]*?;/)[0]);const s=await svc.review.settings(admin);assert.deepEqual(s.categories.filter(c=>c.enabled).map(c=>c.id).sort(),[ids.Final,ids.Drink].sort());assert.equal(s.categories.filter(c=>!c.enabled).length,3);});
test('Settings: Prep Syrup Garnish recipes cannot be searched, suggested or mapped',async()=>{for(const name of ['Prep','Syrup','Garnish']){const c=await category(name),{r}=await categorized(name,c),a=fact({name});await ingest([a]);const q=await svc.mappings(admin,period);assert.equal(q.targets.length,0);assert.equal(q.items.find(i=>i.id===a.itemId).assistance.quality,'NONE');await assert.rejects(map(a.itemId,r),e=>e.code==='ineligible_mapping_target');}});
test('Settings: a new category appears automatically and starts disabled',async()=>{const id=await category('Retail');assert.equal((await svc.review.settings(admin)).categories.find(c=>c.id===id).enabled,false);});
test('Settings: Admin enables new category, audits policy, and leaves Recipe/domain facts unchanged',async()=>{const id=await category('Retail'),{r}=await categorized('Retail item',id),before=await f.repository.read();await settings([id]);const q=await svc.mappings(admin,period);assert.equal(q.targets[0].id,r.id);assert.equal(q.targets[0].categoryName,'Retail');assert.deepEqual(await f.repository.read(),before);const a=(await pool.query('SELECT * FROM wahi_v2.cogs_settings_audit')).rows;assert.equal(a.length,1);assert.equal(a[0].enabled,true);assert.equal(a[0].actor_id,admin.id);});
test('Settings: Drink rename to Cocktails preserves eligibility identity',async()=>{const id=await category('Drink'),{r}=await categorized('Pina Colada',id);await settings([id]);await f.run('updateRecipeCategory',{categoryId:id,name:'Cocktails',sortOrder:0,active:true});const s=await svc.review.settings(admin);assert.equal(s.categories.find(c=>c.id===id).enabled,true);assert.equal((await svc.mappings(admin,period)).targets.find(t=>t.id===r.id).categoryName,'Cocktails');});
test('Settings: disable category removes new targets and cached suggestions without changing confirmed mappings',async()=>{const {r}=await recipe(),a=fact({name:'Dish'}),b=fact({name:'Dish'});await ingest([a,b]);await map(a.itemId,r);await result();const before=(await pool.query('SELECT * FROM wahi_v2.cogs_mappings')).rows;await svc.mappings(admin,period);await settings([]);const q=await svc.mappings(admin,period);assert.equal(q.targets.length,0);assert.equal(q.items.find(i=>i.id===b.itemId).assistance.quality,'NONE');assert.equal(q.items.find(i=>i.id===a.itemId).target.eligible,false);assert.deepEqual((await pool.query('SELECT * FROM wahi_v2.cogs_mappings')).rows,before);assert.equal((await svc.report(admin,period)).dirtyRows,0);assert.equal((await svc.report(admin,period)).summary.total,'2.000000000000');await assert.rejects(map(b.itemId,r),e=>e.code==='ineligible_mapping_target');assert.equal((await pool.query('SELECT enabled FROM wahi_v2.cogs_settings_audit ORDER BY recorded_at DESC LIMIT 1')).rows[0].enabled,false);});
test('Settings: category reassignment and future activation refresh only candidate assistance',async()=>{const {r}=await recipe(),prep=await category('Prep'),a=fact({name:'Dish'});await ingest([a]);assert.equal((await svc.mappings(admin,period)).items[0].assistance.quality,'EXACT');await f.run('setRecipeCategory',{recipeId:r.id,categoryId:prep,effectiveAt:'2026-09-22T00:00:00.000Z'});assert.equal((await svc.mappings(admin,period)).items[0].assistance.quality,'EXACT');svc.clock=()=>Date.parse('2026-09-23T12:00:00Z');assert.equal((await svc.mappings(admin,period)).items[0].assistance.quality,'NONE');});
test('Execution: many Toast identities share one Recipe while quantities, revenue and percentages remain independent',async()=>{const c=await category('Drink'),p=await f.bought('Base','2'),r=await f.recipe('Mai Tai',[{ingredientId:p.id,quantity:'2',unit:'each'}],'12','each');await f.run('setRecipeCategory',{recipeId:r.id,categoryId:c,effectiveAt:early});await settings([c]);const a=fact({name:'Mai Tai',quantity:'40',netSales:'560'}),b=fact({name:'HH Mai Tai',quantity:'25',netSales:'225'}),e=fact({name:'Event Mai Tai',quantity:'10',netSales:'100'});await ingest([a,b,e]);const before=(await pool.query('SELECT * FROM wahi_v2.sales_facts ORDER BY id')).rows;for(const x of [a,b,e])await map(x.itemId,r);const d=await result();assert.equal(d.summary.quantity,'75');assert.equal(d.summary.total,'300.000000000000');assert.equal(d.summary.netSales,'885.000000000000');assert.equal(d.mapping.mapped,3);assert.equal(d.reconciled,true);for(const [f,total,percent]of [[a,'160.000000000000','28.57'],[b,'100.000000000000','44.44'],[e,'40.000000000000','40.00']]){const row=d.rows.find(x=>x.id===f.itemId);assert.equal(row.total,total);assert.equal(row.percent,percent);assert.equal(Number(row.netSales),Number(f.netSales));}assert.deepEqual((await pool.query('SELECT * FROM wahi_v2.sales_facts ORDER BY id')).rows,before);const policies=(await pool.query('SELECT * FROM wahi_v2.cogs_mappings')).rows;assert.equal(new Set(policies.map(p=>p.recipe_id)).size,1);assert.ok(policies.every(p=>p.quantity===null&&p.unit===null&&p.mode==='execution'));});
test('Execution: Happy Hour may use a separate eligible Recipe',async()=>{const c=await category('Drink'),a=await categorized('Mai Tai',c,'4','12'),b=await categorized('HH Mai Tai',c,'2','6');await settings([c]);const x=fact({quantity:'40',netSales:'560'}),y=fact({quantity:'25',netSales:'225'});await ingest([x,y]);await map(x.itemId,a.r);await map(y.itemId,b.r);const d=await result();assert.equal(d.summary.total,'210.000000000000');assert.equal(d.summary.quantity,'65');assert.equal(d.reconciled,true);});
test('Execution: historical output changes select each complete Recipe execution, not current or 1-each output',async()=>{const c=await category('Final'),{p,r}=await categorized('Finished',c,'4','12');await settings([c]);await f.run('reviseRecipe',{recipeId:r.id,lines:[{ingredientId:p.id,quantity:'2',unit:'each'}],outputQuantity:'24',outputUnit:'each',steps:[],effectiveAt:day+'T18:00:00.000Z'});const a=fact(),b=fact({itemId:a.itemId,saleAt:day+'T19:00:00.000Z'});await ingest([a,b]);await map(a.itemId,r);const d=await result();assert.equal(d.summary.total,'12.000000000000');assert.equal(d.summary.coverage.historical.quantity,'2');});
test('Execution: nested Prep yield remains recursive and its costs are not duplicated',async()=>{const c=await category('Final'),p=await f.bought('Raw','12'),prep=await f.recipe('Prep',[{ingredientId:p.id,quantity:'1',unit:'each'}],'12','each'),r=await f.recipe('Finished',[{ingredientId:prep.output,quantity:'3',unit:'each'}],'2','each');await f.run('setRecipeCategory',{recipeId:r.id,categoryId:c,effectiveAt:early});await settings([c]);const a=fact({quantity:'5'});await ingest([a]);await map(a.itemId,r);assert.equal((await result()).summary.total,'15.000000000000');});
test('Execution: Exact and bulk confirmation require no portion configuration',async()=>{const {r}=await recipe('3','Dish'),a=fact({name:'Dish'}),b=fact({name:'DISH'});await ingest([a,b]);const q=await svc.mappings(admin,period);assert.equal(q.bulk.recent.entries.length,2);const saved=await svc.mappingBulk(admin,{confirmed:true,entries:q.bulk.recent.entries});assert.equal(saved.committed,2);assert.equal((await result()).summary.total,'6.000000000000');assert.equal((await pool.query('SELECT count(DISTINCT recipe_id) n FROM wahi_v2.cogs_mappings')).rows[0].n,'1');});
test('Execution: new mapping API rejects legacy quantity/unit/menu fields',async()=>{const {r}=await recipe(),a=fact();await ingest([a]);for(const extra of [{quantity:'1',unit:'each'},{menuItemId:uuid()}])await assert.rejects(svc.mapping(admin,{itemId:a.itemId,state:'mapped',expectedVersion:0,recipeId:r.id,...extra}),e=>e.name==='ZodError');});
test('Execution: only one current target per Toast GUID, changes are audited and targeted',async()=>{const a=await recipe('2'),b=await recipe('5'),x=fact(),y=fact();await ingest([x,y]);await map(x.itemId,a.r);await map(y.itemId,a.r);await result();await map(x.itemId,b.r,{expectedVersion:1});assert.deepEqual((await pool.query('SELECT item_id FROM wahi_v2.cogs_knowledge WHERE dirty')).rows.map(r=>r.item_id),[x.itemId]);await result();assert.equal((await svc.report(admin,period)).summary.total,'7.000000000000');assert.equal((await pool.query('SELECT count(*) FROM wahi_v2.cogs_mappings WHERE item_id=$1',[x.itemId])).rows[0].count,'1');assert.equal((await svc.mappingHistory(admin,{id:x.itemId})).events[0].next.recipeId,b.r.id);});
test('Settings: stale settings and stale Exact review fail without partial policy writes',async()=>{const {r}=await recipe(),a=fact({name:'Dish'});await ingest([a]);const q=await svc.mappings(admin,period),s=await svc.review.settings(admin);await settings([]);await assert.rejects(svc.review.saveSettings(admin,{expectedVersion:s.version,categoryIds:[finalCategory]}),e=>e.code==='revision_conflict');await assert.rejects(svc.mappingBulk(admin,{confirmed:true,entries:q.bulk.recent.entries}),e=>e.code==='revision_conflict');assert.equal((await pool.query('SELECT count(*) FROM wahi_v2.cogs_mappings')).rows[0].count,'0');});
test('Settings: Manager Staff Lead cannot read or change Mapping Settings',async()=>{for(const actor of [manager,staff,lead]){await assert.rejects(svc.review.settings(actor),e=>e.code==='forbidden');await assert.rejects(svc.review.saveSettings(actor,{expectedVersion:1,categoryIds:[]}),e=>e.code==='forbidden');}});
test('Settings: disabled Admin cannot change eligibility',async()=>{const s=await svc.review.settings(admin);await pool.query("UPDATE wahi_v2.users SET status='disabled' WHERE id=$1",[admin.id]);await assert.rejects(svc.review.saveSettings(admin,{expectedVersion:s.version,categoryIds:[]}),e=>e.code==='forbidden');});
test('Execution: ordinary mapping UI contains no quantity/unit controls and includes category/settings labels',async()=>{const source=await fs.readFile(path.join(__dirname,'../review/public/mapping-ui.js'),'utf8');assert.doesNotMatch(source,/name="(?:quantity|unit)"|Recipe quantity per sold unit|Recipe unit|Search Wahi Recipe\/menu portion/);assert.match(source,/Eligible Recipe Categories/);assert.match(source,/One Toast sold unit = one complete execution/);assert.match(source,/categoryName/);});
test('Execution: current fallback costs the complete current output and remains estimated',async()=>{const c=await category('Final'),{r}=await categorized('Finished',c,'7','12');await settings([c]);const a=fact({saleAt:'2026-07-15T16:00:00.000Z'});await ingest([a]);await map(a.itemId,r);const d=await result();assert.equal(d.summary.total,'7.000000000000');assert.equal(d.summary.coverage.current.quantity,'1');assert.equal(d.rows[0].status,'ESTIMATED');});
test('Execution: alternate purchase basis remains explicit and scales to complete defined output',async()=>{const c=await category('Final'),{r}=await categorized('Finished',c,'2','12');await settings([c]);const option=(await f.run('createPurchaseOption',{ingredientId:r.output,label:'finished pack',contentQuantity:'12',contentUnit:'each'})).id;await f.run('addPrice',{purchaseOptionId:option,amount:'7',currency:'USD',effectiveAt:early});await f.run('selectBasis',{ingredientId:r.output,kind:'purchase',purchaseOptionId:option,effectiveAt:'2026-08-02T00:00:00.000Z'});const a=fact();await ingest([a]);await map(a.itemId,r);const d=await result();assert.equal(d.summary.total,'7.000000000000');assert.equal(d.summary.coverage.alternate.quantity,'1');assert.equal(d.rows[0].status,'ESTIMATED');});
test('Execution: missing finished output remains a mapped cost blocker without inferred yield',async()=>{const c=await category('Final'),p=await f.bought('Part','2'),r=await f.recipe('Finished',[{ingredientId:p.id,quantity:'1',unit:'each'}],null,null);await f.run('setRecipeCategory',{recipeId:r.id,categoryId:c,effectiveAt:early});await settings([c]);const a=fact();await ingest([a]);await map(a.itemId,r);const d=await result();assert.equal(d.rows[0].mappingState,'mapped');assert.equal(d.rows[0].status,'UNRESOLVED');assert.equal(d.summary.coverage.unresolved.quantity,'1');assert.equal((await svc.detail(admin,{...period,id:a.itemId})).days[0].payload.buckets[0].blockers[0].reason,'missing_yield');});
